"""Embed data-only shortcut presets; --check detects stale generated C++ data."""
from pathlib import Path
import argparse
import json

ROOT = Path(__file__).resolve().parents[2]
TARGET = ROOT / "src/apps/mplayerc/bridge/BuiltinProfiles.h"


def generate():
    blocks = ["// SPDX-License-Identifier: GPL-3.0-or-later\n",
              "// Generated by tools/bridge/generate_profiles.py; edit bridge/profiles/*.json.\n",
              "#pragma once\n\nnamespace Bridge {\n"]
    for name in ("youtube", "bilibili"):
        data = (ROOT / "bridge/profiles" / f"{name}.json").read_text(encoding="utf-8")
        json.loads(data)
        if ')BRIDGEPROFILE"' in data:
            raise ValueError("Preset contains the reserved C++ raw-string delimiter")
        blocks.append(f'inline constexpr char Builtin{name.title()}[] = R"BRIDGEPROFILE({data})BRIDGEPROFILE";\n')
    blocks.append("} // namespace Bridge\n")
    return "".join(blocks)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = generate()
    if args.check:
        if not TARGET.exists() or TARGET.read_text(encoding="utf-8") != generated:
            raise SystemExit("Embedded presets are stale. Run tools/bridge/generate_profiles.py.")
        print("Embedded profiles match JSON sources.")
    else:
        TARGET.write_text(generated, encoding="utf-8", newline="\n")
